-- POST: 17e69f50 — Vancouver Infill Development
-- ============================================================
UPDATE blog_posts SET
  title_zh = '温哥华填充开发与地块分割2026：成本与SSMUH许可',
  excerpt_zh = '2026年温哥华填充开发完整指南。Bill 44/SSMUH下的地块分割规则、$55万-$150万的建筑成本范围、18-30个月时间表。',
  content_zh = '<h2>什么是填充开发？</h2><p>填充开发是指在现有已开发地块上建造新住宅——既可以将单户地块分割成两个较小的地块并各建一栋新房，也可以不分割地块直接增加单元（复式、三层或多层）。</p><p>根据BC省SSMUH立法（Bill 44，2024年中），大多数温哥华单户地块现在可以容纳3-6个单元。结合市级地块分割规则和临街宽度放宽政策，这为温哥华业主提供了一个真正的变现地块未充分利用密度的途径。</p><h2>2026年填充开发成本明细（大温哥华地区）</h2><p>基于Reno Stars已完成的8个项目数据：</p><ul><li><strong>单个新建填充住宅（2,000-2,500平方尺）：</strong>$550,000-$850,000建造费用，含许可审批9-14个月。不含土地成本。</li><li><strong>复式住宅（并排，每单元1,500-1,800平方尺）：</strong>$750,000-$1,150,000总计。10-16个月。</li><li><strong>三层/四层（不分割地块的多层）：</strong>$850,000-$1,500,000总计。常与保留前方现有房屋一起进行。12-18个月。</li><li><strong>地块分割+2栋独立住宅：</strong>$900,000-$1,400,000总计。另加地块分割及测量费$20,000-$45,000。14-24个月。</li></ul><h2>SSMUH+地块分割许可流程</h2><ol><li><strong>分区+临街宽度核实（1-2周）：</strong>确认地块是否符合温哥华/本拿比/高贵林市规定。最小地块宽度通常33-50尺。</li><li><strong>土地测量师+BC Assessment分割申请（8-16周）：</strong>法律分割为土地产权办公室备案，含新PID分配和税册分割。</li><li><strong>城市规划预申请会议（4-6周）：</strong>讨论体量、退缩、停车、容积率。</li><li><strong>建筑许可申请（12-22周）：</strong>温哥华当前队列时间。</li><li><strong>施工：</strong>每栋住宅8-14个月。</li><li><strong>最终入住+新地址：</strong>施工后测量、市政地址分配、各新地块公用设施连接。</li></ol><h2>ROI数学：何时才能盈利？</h2><p>典型温哥华填充项目（东区$2.5M角落地块一半分割）：</p><ul><li>土地成本基准（分割后您的一半份额）：$1.2M</li><li>建造成本：$650,000</li><li>总投入：约$1.85M</li><li>完工后市值：$2.3M-$2.5M</li><li>净 equity 收益：$450K-$650K（14-18个月内）</li></ul><h2>常见陷阱</h2><ul><li><strong>树木保护规定：</strong>温哥华树木附例保护胸径30cm以上的树木。保护树木的位置可能影响设计。</li><li><strong>服务容量：</strong>地块增加2-4个单元可能需要城市下水道升级（$15K-$40K）。</li><li><strong>地质问题：</strong>温哥华下方黏土需要场地特定地基工程。</li></ul><h2>常见问题</h2><h3>SSMUH下可以分割50x100尺的温哥华地块吗？</h3><p>大多数情况下可以，分割成两个25x100尺地块，每个新建一栋住宅（或更好ROI的复式）。</p><h3>完整填充开发时间线是多久？</h3><p>从首次咨询到新住宅入住：通常18-30个月。</p><h3>Reno Stars 处理分割备案吗？</h3><p>是的——全程服务，含BC土地测量师协调、BC Assessment分割申请和土地产权办公室新PID备案。</p>',
  meta_title_zh = '温哥华填充开发与地块分割2026：成本与SSMUH许可 | 聚星装修',
  meta_description_zh = '2026年温哥华填充开发完整指南。Bill 44/SSMUH下的地块分割规则、$55万-$150万的建筑成本范围、18-30个月时间表。',
  focus_keyword_zh = '温哥华填充开发',
  seo_keywords_zh = '温哥华填充开发,地块分割,SSMUH,多户住宅开发,温哥华建筑许可,填充开发成本'
WHERE id = '17e69f50-74b9-469e-8b87-11d3a4ed74ef'
  AND content_zh LIKE '%待编辑团队完整翻译%';

